8b-99b4-4f86-a6e0-991c7d061f72", "type": "concept", "title": "Freemium"}], "description": "Gist: Good SaaS pricing aligns revenue with customer value and product usage."}, {"id": "939f2b88-9354-4a42-88a7-969fbe41a26e", "type": "subtopic", "title": "Platform pricing", "children": [{"id": "21134821-efa0-40ba-9cb5-cd47a5cef44d", "type": "concept", "title": "Cross-side network effects"}, {"id": "1ef257a9-19bc-4274-9d7e-35c5b87edfec", "type": "concept", "title": "Subsidy side"}, {"id": "a2f97827-0155-4b63-8d5d-22056c342a84", "type": "concept", "title": "Take rate"}, {"id": "dad289c6-7699-4056-9a3f-121c4dad1921", "type": "concept", "title": "Marketplace liquidity"}], "description": "Gist: Two-sided markets require pricing decisions across different user groups."}]}, {"id": "0950619f-06b4-4364-9dd4-ffc40f03311b", "type": "topic", "title": "Revenue Management and Dynamic Pricing", "description": "Apply yield management, capacity constraints, demand forecasting, and dynamic price optimization.", "children": [{"id": "74ec143f-e390-4c0c-9ee5-36502b648d73", "type": "subtopic", "title": "Capacity and perishability", "children": [{"id": "49d214a6-f271-4b6d-95ba-29b0c7fd7d18", "type": "concept", "title": "Airline seats"}, {"id": "3481c2ba-e7f2-4abd-a357-285c6397dea5", "type": "concept", "title": "Hotel rooms"}, {"id": "cd30dee3-8796-4d23-85e0-4e8888bec9f6", "type": "concept", "title": "Events"}, {"id": "1ad4baef-d6d4-45a6-ae03-cc559773da6f", "type": "concept", "title": "Capacity constraints"}], "description": "Gist: Revenue management is powerful when inventory is limited or perishable."}, {"id": "f61a8018-78aa-48b3-952f-b76b0f6a8a12", "type": "subtopic", "title": "Dynamic pricing", "children": [{"id": "02b38668-9f5e-4d1a-809f-ce9aa176ba52", "type": "concept", "title": "Demand forecasting"}, {"id": "334f50bb-0ce1-4364-a9dd-a597f6312d28", "type": "concept", "title": "Yield management"}, {"id": "1e5f71e5-854f-488f-bff8-ea7d23fa35d2", "type": "concept", "title": "Surge pricing"}, {"id": "c54a11da-f8c6-41a1-a2f8-9169428b4ff1", "type": "concept", "title": "Price optimization"}], "description": "Gist: Dynamic prices respond to demand, time, inventory, competition, and customer context."}, {"id": "7880c816-ae0d-4fb7-a740-66b377a7f730", "type": "subtopic", "title": "Governance of algorithms", "children": [{"id": "41892762-985e-4713-b851-226adbdb6c85", "type": "concept", "title": "Model drift"}, {"id": "c77206f9-148e-41ff-b315-203e64cbcefb", "type": "concept", "title": "Bias risk"}, {"id": "fc8c45a2-cd92-4e5c-ac12-d4a1e8c49c5d", "type": "concept", "title": "Customer communication"}, {"id": "528c3c62-f707-4378-8f0d-853cbb647083", "type": "concept", "title": "Override rules"}], "description": "Gist: Dynamic pricing must be monitored for fairness, transparency, and unintended outcomes."}]}, {"id": "bc6709e0-da6a-443e-8787-90935f6452f9", "type": "topic", "title": "B2B Pricing, Negotiation, and Sales Enablement", "description": "Equip students to design pricing processes for enterprise selling, discount governance, and value negotiation.", "children": [{"id": "9403be17-72e9-4fb9-8307-e661808c42ed", "type": "subtopic", "title": "B2B value quantification", "children": [{"id": "d32a723a-2591-47c0-9dbc-7ab9a64e5250", "type": "concept", "title": "ROI case"}, {"id": "328e58f5-c862-476b-ad0f-b7b9a22cdba2", "type": "concept", "title": "Total cost of ownership"}, {"id": "5b376586-bfeb-47ba-939e-7a0fabc61f10", "type": "concept", "title": "Economic buyer"}, {"id": "4bf32826-f5fa-47ef-a3a0-34e032945433", "type": "concept", "title": "Use-case value"}], "description": "Gist: B2B pricing depends on quantified business value, procurement dynamics, and buyer economics."}, {"id": "fd0291b5-96a4-4151-b91a-e68b2a2b2ca4", "type": "subtopic", "title": "Discount governance", "children": [{"id": "3548c86d-7a7b-45f9-a870-a479f58ebc3f", "type": "concept", "title": "Discount waterfall"}, {"id": "a46b5127-55f0-4f1d-9461-a7bf2fc26b8f", "type": "concept", "title": "Approval thresholds"}, {"id": "9b286069-40dd-4ba9-bc84-922d69eced66", "type": "concept", "title": "Deal desk"}, {"id": "86428cb3-f589-431a-8440-9ef1649b05e8", "type": "concept", "title": "Sales incentives"}], "description": "Gist: Firms need rules that prevent unmanaged discounting from eroding profit."}, {"id": "2f01b75e-87b2-46b4-832c-7921282c1d64", "type": "subtopic", "title": "Negotiation support", "children": [{"id": "6917d6e1-fcbe-4426-8477-ecdbc9d3ec21", "type": "concept", "title": "Walk-away price"}, {"id": "c0b09855-9d6f-42ad-a865-f91959397905", "type": "concept", "title": "Concession strategy"}, {"id": "c1d6b9c2-caf6-457a-8f99-bac917a9acaf", "type": "concept", "title": "Value proof"}, {"id": "9557bcf8-918f-4a80-8bb2-56fd0ac46142", "type": "concept", "title": "Contract terms"}], "description": "Gist: Sales teams need tools and narratives to defend value and trade concessions."}]}, {"id": "7976491c-17df-4eae-81e7-f93b4ba685e8", "type": "topic", "title": "Pricing Metrics, Analytics, Experiments, and ROI", "description": "Measure pricing performance with margin, volume, CLV, experiments, attribution, and pricing dashboards.", "children": [{"id": "871cd2d4-19e5-4cb3-8e49-b7470f5f3683", "type": "subtopic", "title": "Pricing metrics", "children": [{"id": "a3d7c456-beaf-4999-bb20-5e41faff39b4", "type": "concept", "title": "Gross margin"}, {"id": "35fd4d88-2b53-4f92-bcd4-fa5879ecfe7b", "type": "concept", "title": "Price realization"}, {"id": "249c3ae7-1982-4135-bbc1-9c2962c0168e", "type": "concept", "title": "Win rate"}, {"id": "0cf913b4-6229-487c-b49f-839dfbdc2f86", "type": "concept", "title": "Customer lifetime value"}], "description": "Gist: Pricing performance requires a dashboard beyond revenue alone."}, {"id": "d1e1daeb-685d-414c-904e-3f7015755b83", "type": "subtopic", "title": "Price analytics", "children": [{"id": "579688bf-f0af-4e65-91ce-4763013109fa", "type": "concept", "title": "Waterfall analysis"}, {"id": "1ac60d3f-acba-4214-8da2-4bef375c8cde", "type": "concept", "title"